❌ Vulnerable (Current Implementation)✅ Secure (Patched Implementation) <pre><code>// Direct string interpolation allows payload breakout
const query = `SELECT * FROM Products WHERE id = ${req.params.id}`;
await sequelize.query(query);
</code></pre> <pre><code>// Parameterized query using Sequelize replacements
const query = 'SELECT * FROM Products WHERE id = :id';
await sequelize.query(query, {
  replacements: { id: req.params.id },
  type: QueryTypes.SELECT
});
</code></pre>

❌ Vulnerable (Public Directory Indexing)✅ Secure (Authenticated Controlled File Access) <pre><code>// server.ts
app.use('/ftp', serveIndex('ftp', { icons: true }));
app.use('/ftp', express.static('ftp'));
</code></pre> <pre><code>// server.ts - Remove public directory listing
// Documents are served through an authenticated controller enforcing access control
app.get('/api/documents/:filename', authenticateUser, (req: Request, res: Response) =&gt; {
  const allowedRoles = ['EXECUTIVE', 'LEGAL_ADMIN'];
  if (!allowedRoles.includes(req.user.role)) {
    return res.status(403).json({ error: "Access Denied: Insufficient Permissions" });
  }

  // Prevent Path Traversal (CWE-22)
  const safeFilename = path.basename(req.params.filename);
  const filePath = path.resolve(__dirname, '../secure-storage', safeFilename);

  res.sendFile(filePath);
});
</code></pre>

