❌ Vulnerable (Direct Stack Trace Return)✅ Secure (Generic Error with Unique Correlation ID) <pre><code>app.use((err: Error, req: Request, res: Response, next: NextFunction) =&gt; {
  // Exposes technical details to unauthenticated visitors
  res.status(500).json({
    message: err.message,
    stack: err.stack
  });
});
</code></pre> <pre><code>import { v4 as uuidv4 } from 'uuid';
import logger from './lib/logger';

app.use((err: Error, req: Request, res: Response, next: NextFunction) =&gt; {
  const incidentId = uuidv4();

  // Log technical details internally for engineering teams
  logger.error(`[Incident ${incidentId}] Error processing ${req.method} ${req.url}:`, err);

  // Return sanitized, generic response to user
  res.status(500).json({
    error: "An unexpected internal server error occurred.",
    referenceId: incidentId
  });
});
</code></pre>

❌ Vulnerable (Public Binding)✅ Secure (Dedicated Internal Port or Middleware Guard) <pre><code>// server.ts
epimetheus.instrument(app); // Defaults to exposing /metrics publicly
</code></pre> <pre><code>// server.ts - Bind metrics to an isolated internal management port (e.g. 9100)
import http from 'http';
import express from 'express';

const internalMetricsApp = express();
epimetheus.instrument(internalMetricsApp);

// Only bind to localhost or internal cluster network interface
internalMetricsApp.listen(9100, '127.0.0.1', () =&gt; {
  console.log('Metrics server running securely on internal port 9100');
});

// Alternatively, guard the public route with mutual TLS or Bearer token auth:
app.use('/metrics', (req: Request, res: Response, next: NextFunction) =&gt; {
  const authHeader = req.headers.authorization;
  if (authHeader !== `Bearer ${process.env.METRICS_TOKEN}`) {
    return res.status(401).json({ error: "Unauthorized metrics access" });
  }
  next();
});
</code></pre>

❌ Vulnerable (Static Unmonitored Whitelist)✅ Secure (Strict Relative Redirects or Explicit Confirmation Modal) <pre><code>// utils.ts
export const redirectWhitelist = [
  'https://blockchain.info/address/1AbKfgHTnnJhmGCJk8R3mA7xNyHbgegCDT'
];
</code></pre> <pre><code>// routes/redirect.ts
// Option A: Strictly restrict to relative local paths
export function safeRedirect(req: Request, res: Response) {
  const target = req.query.to as string;

  // Ensure target begins with a single '/' and not '//' (protocol-relative)
  if (target &amp;&amp; target.startsWith('/') &amp;&amp; !target.startsWith('//')) {
    return res.redirect(target);
  }

  // Option B: For external redirects, route through an interstitial warning screen
  return res.status(400).json({ error: "External redirects require explicit user consent" });
}
</code></pre>

❌ Vulnerable (Trusting Client Input)✅ Secure (Server-Side Schema Validation via Joi/Zod) <pre><code>// routes/register.ts
UserModel.create({
  email: req.body.email,
  password: req.body.password
});
</code></pre> <pre><code>import { z } from 'zod';

// Strict registration schema enforced on API boundary
const RegistrationSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
  passwordRepeat: z.string().min(8),
}).refine((data) =&gt; data.password === data.passwordRepeat, {
  message: "Passwords do not match",
  path: ["passwordRepeat"],
});

export function registerSecure () {
  return async (req: Request, res: Response, next: NextFunction) =&gt; {
    const validation = RegistrationSchema.safeParse(req.body);
    if (!validation.success) {
      return res.status(400).json({ errors: validation.error.format() });
    }

    // Proceed with user creation
    const user = await UserModel.create({
      email: validation.data.email,
      password: security.hashPassword(validation.data.password),
      role: roles.customer
    });
    res.status(201).json({ status: 'success', data: user });
  };
}
</code></pre>

